void delay_ms(uint32_t ms) {
    // Set SysTick clock source to AHB/8
    SysTick->CTRL |= SysTick_CTRL_CLKSOURCE_Msk;

    // Reload SysTick counter with 71999 (1ms at 72MHz)
    SysTick->LOAD = 71999;

    // Clear SysTick current value
    SysTick->VAL = 0;

    // Wait until SysTick interrupt occurs
    while ((SysTick->CTRL & SysTick_CTRL_COUNTFLAG_Msk) == 0);
